`timescale 1ns/1ns
module Top;
  int a, b, a2;
  task count(output int result);
    static int calls = 0;
    int seen;
    calls++;
    seen = calls;
    #2;
    result = seen;
  endtask
  task count2(output int result);
    static int calls = 0;
    static int seen;
    calls++;
    seen = calls;
    #2;
    result = seen;
  endtask
  initial begin count(a); count2(a2); end
  initial begin #1; count(b); end
  initial begin #1; count2(b); end
  initial begin #10 $display("a=%0d b=%0d a2=%0d", a, b, a2); end
endmodule
